import { ValidationError } from '../errors.js';
import { nightsBetween, parseDay } from './dates.js';

const MAX_NIGHTS = 30;
const MAX_GUEST = 80;

// Builds a booking { room, guest, start, end } from request input, or throws
// a ValidationError naming the first bad field (room, guest, start, end).
export function makeBooking(input) {
  if (input === null || typeof input !== 'object' || Array.isArray(input))
    throw new ValidationError('booking', 'booking must be an object');
  const { room, guest, start, end } = input;
  if (typeof room !== 'string' || !room.trim())
    throw new ValidationError('room', 'room is required');
  const name = typeof guest === 'string' ? guest.trim() : '';
  if (!name) throw new ValidationError('guest', 'guest is required');
  if (name.length > MAX_GUEST)
    throw new ValidationError('guest', 'guest must be at most 80 characters');
  if (parseDay(start) === null)
    throw new ValidationError('start', 'start must be a date like 2025-03-01');
  if (parseDay(end) === null)
    throw new ValidationError('end', 'end must be a date like 2025-03-04');
  const nights = nightsBetween(start, end);
  if (nights < 1) throw new ValidationError('end', 'end must be after start');
  if (nights > MAX_NIGHTS)
    throw new ValidationError('end', 'a stay is at most 30 nights');
  return { room, guest: name, start, end };
}

import { AppError, ConflictError, NotFoundError, ValidationError } from '../errors.js';
import { errorBody, json } from './respond.js';
import { matchRoute } from './router.js';

function parseBody(text) {
  let value;
  try {
    value = JSON.parse(text);
  } catch {
    throw new AppError('BAD_JSON', 'request body is not valid JSON');
  }
  if (value === null || typeof value !== 'object' || Array.isArray(value))
    throw new AppError('BAD_JSON', 'request body must be a JSON object');
  return value;
}

function failure(error) {
  if (error instanceof ValidationError)
    return json(400, errorBody('VALIDATION', error.message, { field: error.field }));
  if (error instanceof NotFoundError) return json(404, errorBody('NOT_FOUND', error.message));
  if (error instanceof ConflictError) return json(409, errorBody('CONFLICT', error.message));
  if (error instanceof AppError && error.code === 'BAD_JSON')
    return json(400, errorBody('BAD_JSON', error.message));
  return json(500, errorBody('INTERNAL', 'internal error'));
}

export function createHandler(service) {
  return function handle(request) {
    try {
      const route = matchRoute(request.method, request.path);
      switch (route.name) {
        case 'create':
          return json(201, { booking: service.book(parseBody(request.body)) });
        case 'list':
          return json(200, { bookings: service.list({ room: request.query?.room }) });
        case 'cancel':
          return json(200, { id: service.cancel(route.params.id) });
        case 'method':
          return json(405, errorBody('METHOD_NOT_ALLOWED', 'method not allowed'));
        default:
          return json(404, errorBody('NOT_FOUND', 'no such route'));
      }
    } catch (error) {
      return failure(error);
    }
  };
}

// Finds the route for a request: { name, params }. `name` is 'none' when no
// path fits and 'method' when the path exists but not for this method.
export function matchRoute(method, path) {
  if (path === '/bookings') {
    if (method === 'POST') return { name: 'create', params: {} };
    if (method === 'GET') return { name: 'list', params: {} };
    return { name: 'method', params: {} };
  }
  const match = /^\/bookings\/([^/]+)$/.exec(path);
  if (match) {
    if (method === 'DELETE')
      return { name: 'cancel', params: { id: decodeURIComponent(match[1]) } };
    return { name: 'method', params: {} };
  }
  return { name: 'none', params: {} };
}

import { makeBooking } from '../domain/booking.js';
import { ConflictError, NotFoundError } from '../errors.js';
import { createSequence } from './ids.js';

// Two stays overlap when each starts before the other ends; check-out day is free.
const overlaps = (a, b) => a.start < b.end && b.start < a.end;

export function createBookingService({ rooms }) {
  const bookings = new Map();
  const nextId = createSequence('b');
  return {
    // Returns the saved booking: { id, room, guest, start, end }.
    book(input) {
      const booking = makeBooking(input);
      if (!rooms.has(booking.room)) throw new NotFoundError('room', booking.room);
      const clash = [...bookings.values()].find(
        (other) => other.room === booking.room && overlaps(other, booking),
      );
      if (clash)
        throw new ConflictError(
          'room ' + booking.room + ' is booked from ' + clash.start + ' to ' + clash.end,
        );
      const saved = { id: nextId(), ...booking };
      bookings.set(saved.id, saved);
      return saved;
    },
    // Returns the id of the cancelled booking.
    cancel(id) {
      if (!bookings.delete(id)) throw new NotFoundError('booking', id);
      return id;
    },
    list({ room } = {}) {
      const all = [...bookings.values()];
      return room === undefined ? all : all.filter((b) => b.room === room);
    },
  };
}
